import urllib.parse

def parse_query_string(query):
    """
    Parses a URL query string into a dict mapping each key to a list of decoded values.
    Ignores a leading ?. Uses urllib.parse semantics for percent decoding and blank values.
    """
    if query.startswith('?'):
        query = query[1:]

    if not query:
        return {}

    parsed_query = urllib.parse.parse_qs(query)
    result = {}

    for key, values in parsed_query.items():
        # parse_qs returns values as lists of strings.
        # We need to handle potential blank values if they exist in the input,
        # although parse_qs usually handles empty values by not including them
        # or returning an empty list depending on the input format.
        # The requirement is to map key to a list of decoded values.
        result[key] = values

    return result

def parse_env_lines(text):
    env_vars = {}
    for line in text.splitlines():
        # Ignore blank lines and lines starting with #
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith('#'):
            continue

        # Split on the first equals sign
        if '=' in stripped_line:
            key, value = stripped_line.split('=', 1)
            # Strip surrounding whitespace from keys and values
            key = key.strip()
            value = value.strip()
            env_vars[key] = value
    return env_vars

def parse_size_bytes(value):
    if not isinstance(value, str):
        raise ValueError("Input must be a string")

    value = value.strip()
    if not value:
        raise ValueError("Input string cannot be empty")

    # Check for negative numbers (though int conversion handles this, explicit check is good)
    if value.startswith('-'):
        raise ValueError("Negative numbers are not allowed")

    # Determine the numeric part and the unit part
    unit = ""
    numeric_str = value

    # Check for units (case-insensitive)
    if value.upper().endswith('B'):
        unit = 'B'
        numeric_str = value[:-1]
    elif value.upper().endswith('KB'):
        unit = 'KB'
        numeric_str = value[:-2]
    elif value.upper().endswith('MB'):
        unit = 'MB'
        numeric_str = value[:-2]
    elif value.upper().endswith('GB'):
        unit = 'GB'
        numeric_str = value[:-2]
    else:
        # If no recognized unit suffix, assume it's just a number (no unit)
        unit = ''
        numeric_str = value

    try:
        # Reject decimals: check if the numeric string contains a decimal point
        if '.' in numeric_str:
            raise ValueError("Decimals are not allowed")

        # Parse the integer
        size = int(numeric_str)

        # Reject negative numbers (already partially checked, but ensures final result is positive)
        if size < 0:
            raise ValueError("Negative numbers are not allowed")

        # Calculate the final size based on the unit
        if unit == 'B':
            return size
        elif unit == 'KB':
            return size * 1024
        elif unit == 'MB':
            return size * 1024**2
        elif unit == 'GB':
            return size * 1024**3
        else:
            # If unit is empty, it's just the integer value (no unit suffix found)
            return size

    except ValueError as e:
        # Re-raise with a more specific message if it's a parsing error we control
        if "Decimals are not allowed" in str(e) or "Negative numbers are not allowed" in str(e):
            raise ValueError(f"Invalid format or value: {value}") from e
        # If it's a general int conversion error (e.g., non-numeric characters remaining)
        raise ValueError(f"Invalid size format or unknown unit: {value}") from e
    except Exception as e:
        # Catch any other unexpected errors
        raise ValueError(f"An unexpected error occurred while parsing {value}: {e}")

def parse_semver(value):
    """
    Parses a semantic version string MAJOR.MINOR.PATCH with an optional leading v.
    Returns a tuple of three integers (MAJOR, MINOR, PATCH).
    Raises ValueError if the format is incorrect (missing parts, non-integers, or negative numbers).
    """
    if value.startswith('v'):
        value = value[1:]

    parts = value.split('.')

    if len(parts) != 3:
        raise ValueError("Semantic version string must have exactly three parts (MAJOR.MINOR.PATCH).")

    major_str, minor_str, patch_str = parts[0], parts[1], parts[2]

    try:
        major = int(major_str)
        minor = int(minor_str)
        patch = int(patch_str)
    except ValueError:
        raise ValueError("All version components must be integers.")

    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Version components cannot be negative.")

    return (major, minor, patch)

def parse_bool(value):
    value = str(value).strip().lower()
    if value in ('true', 'yes', 'y', '1', 'on'):
        return True
    elif value in ('false', 'no', 'n', '0', 'off'):
        return False
    else:
        raise ValueError(f"Invalid boolean value: {value}")

