    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def flatten_one_level(items):
    """
    Flattens one nesting level from an iterable of iterables.
    Strings are treated as scalar values and are not expanded.
    """
    result = []
    for item in items:
        if isinstance(item, (list, tuple)):
            result.extend(item)
        else:
            result.append(item)
    return result

def chunked_list(items, size):
    if size <= 0:
        raise ValueError("size must be positive")

    if not items:
        return []

    result = []
    for i in range(0, len(items), size):
        chunk = items[i:i + size]
        result.append(chunk)

    return result

def windowed(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    if size > len(items):
        return []

    result = []
    for i in range(len(items) - size + 1):
        window = items[i:i + size]
        result.append(tuple(window))
    return result

