def group_count(rows, key):
    counts = {}
    for row in rows:
        if key in row:
            value = row[key]
            if value is None:
                counts[None] = counts.get(None, 0) + 1
            else:
                counts[value] = counts.get(value, 0) + 1
        else:
            # Use None for rows missing the key
            counts[None] = counts.get(None, 0) + 1
    return counts

def group_sum(rows, key, value_key):
    result = {}
    for row in rows:
        # Determine the grouping key. If key is None, use None.
        group_key = row.get(key)
        if group_key is None:
            group_key = None

        # Determine the value to sum. If value_key is missing, it's 0.
        value = row.get(value_key, 0)

        # Update the result dictionary
        if group_key not in result:
            result[group_key] = 0

        result[group_key] += value

    return result

def project_fields(rows, fields):
    """
    Returns new dictionaries containing only the requested fields that exist in each input row.
    Preserves row order and field order.
    """
    result = []
    for row in rows:
        new_row = {}
        for field in fields:
            if field in row:
                new_row[field] = row[field]
        result.append(new_row)
    return result

