def percent_change(old, new):
    if old == 0:
        raise ValueError("old cannot be zero")
    return ((new - old) / old) * 100

def clamp_numbers(values, low, high):
    if low > high:
        raise ValueError("low cannot be greater than high")

    clamped_values = []
    for value in values:
        if value < low:
            clamped_values.append(low)
        elif value > high:
            clamped_values.append(high)
        else:
            clamped_values.append(value)
    return clamped_values

def histogram_bins(values, bin_size):
    if bin_size <= 0:
        raise ValueError("bin_size must be positive")

    counts = {}
    for value in values:
        # Calculate the floor bin start
        # For bin_size 10:
        # 0..9 maps to 0 (floor(value / 10) * 10)
        # 10..19 maps to 10 (floor(value / 10) * 10)
        # If value is 5, floor(5/10) * 10 = 0 * 10 = 0
        # If value is 15, floor(15/10) * 10 = 1 * 10 = 10
        bin_start = (value // bin_size) * bin_size

        if bin_start in counts:
            counts[bin_start] += 1
        else:
            counts[bin_start] = 1

    return counts

