def reachable_nodes(graph, start):
    if start not in graph:
        # If the start node is not in the graph keys, it has no outgoing neighbors,
        # but it is still reachable (itself).
        return [start]

    visited = set()
    stack = [start]
    reachable = set()

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            reachable.add(node)

            # Get neighbors, default to an empty list if the node is not in graph
            neighbors = graph.get(node, [])
            for neighbor in neighbors:
                if neighbor not in visited:
                    stack.append(neighbor)

    # Return a sorted list of all reachable nodes
    return sorted(list(reachable))

from collections import deque

def shortest_path_unweighted(graph, start, goal):
    if start == goal:
        return [start]

    # Queue for BFS: stores paths, not just nodes, to reconstruct the path easily.
    # Each element in the queue will be a list representing the path from start to the current node.
    queue = deque([[start]])
    visited = {start}

    while queue:
        path = queue.popleft()
        current_node = path[-1]

        # Check neighbors in the order they appear in the graph's adjacency list
        if current_node in graph:
            neighbors = graph[current_node]
            for neighbor in neighbors:
                if neighbor == goal:
                    return path + [neighbor]

                if neighbor not in visited:
                    visited.add(neighbor)
                    new_path = path + [neighbor]
                    queue.append(new_path)

    return None

def has_cycle_directed(graph):
    """
    Checks if a directed graph has a cycle using Depth First Search (DFS).

    The graph is represented as a dictionary where keys are nodes and values are lists
    of their neighbors.
    """
    # State tracking for DFS:
    # 0: unvisited (white)
    # 1: visiting (gray - currently in the recursion stack)
    # 2: visited (black - finished processing)
    state = {}

    # Initialize all nodes to unvisited
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for neighbor in neighbors:
            all_nodes.add(neighbor)

    for node in all_nodes:
        state[node] = 0

    def dfs(node):
        """
        Recursive helper function for DFS. Returns True if a cycle is found starting from this path.
        """
        state[node] = 1  # Mark as visiting (gray)

        # Get neighbors, handling cases where a node might be a neighbor but not a key in the graph dict
        neighbors = graph.get(node, [])

        for neighbor in neighbors:
            if state.get(neighbor, 0) == 1:
                # Found a back edge to a node currently in the recursion stack (gray) -> Cycle detected
                return True

            if state.get(neighbor, 0) == 0:
                # Unvisited neighbor
                if dfs(neighbor):
                    return True

        state[node] = 2  # Mark as visited (black)
        return False

    # Iterate through all nodes to ensure disconnected components are checked
    for node in all_nodes:
        if state[node] == 0:
            if dfs(node):
                return True

    return False

def dependency_order(dependencies):
    """
    Calculates a topological sort of the dependencies.

    :param dependencies: A dictionary where keys are items and values are lists of items they depend on.
    :return: A deterministic list where dependencies appear before dependents, or raises ValueError on cycles.
    """
    # 1. Build the graph structure and identify all nodes
    all_items = set(dependencies.keys())
    for prereqs in dependencies.values():
        all_items.update(prereqs)

    # Initialize in-degree for all nodes
    in_degree = {item: 0 for item in all_items}

    # Calculate in-degrees: item depends on prereqs, so prereq -> item
    for item, prereqs in dependencies.items():
        for prereq in prereqs:
            if prereq in in_degree:
                in_degree[item] += 1
            else:
                # This case should ideally not happen if all_items is calculated correctly,
                # but handles cases where a prereq is mentioned but not in the initial set of keys.
                in_degree[prereq] = 0

    # 2. Initialize the priority queue (min-heap) with nodes having an in-degree of 0
    import heapq

    ready_heap = []
    for item in sorted(list(all_items)):
        if in_degree[item] == 0:
            heapq.heappush(ready_heap, item)

    result = []

    # 3. Process the heap
    while ready_heap:
        # Choose the lexicographically smallest item first
        current_item = heapq.heappop(ready_heap)
        result.append(current_item)

        # Find items that depend on current_item (successors)
        # We need to iterate through the original dependencies to find dependents.
        for item, prereqs in dependencies.items():
            if current_item in prereqs:
                # current_item is a prerequisite for 'item'
                if item in in_degree:
                    in_degree[item] -= 1
                    if in_degree[item] == 0:
                        heapq.heappush(ready_heap, item)

    # 4. Cycle detection
    if len(result) != len(all_items):
        raise ValueError("Cycle detected in dependencies")

    return result

def reverse_adjacency(graph):
    """
    Computes the reverse adjacency list of a graph represented by an adjacency mapping.

    Args:
        graph (dict): An adjacency mapping where keys are nodes and values are lists
                      of their outgoing neighbors.

    Returns:
        dict: A dictionary where keys are nodes and values are sorted lists of
              incoming neighbors. Includes nodes that only appear as neighbors.
    """
    reverse_graph = {}

    # Initialize all nodes present in the graph (as keys)
    for node in graph:
        if node not in reverse_graph:
            reverse_graph[node] = []

    # Initialize nodes that only appear as neighbors
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for neighbor in neighbors:
            if neighbor not in reverse_graph:
                reverse_graph[neighbor] = []
                all_nodes.add(neighbor)

    # Populate the reverse adjacency list
    for node, neighbors in graph.items():
        for neighbor in neighbors:
            if neighbor in reverse_graph:
                reverse_graph[neighbor].append(node)

    # Sort the incoming neighbors for each node
    for node in reverse_graph:
        reverse_graph[node].sort()

    return reverse_graph

