def json_get_path(data, path, default=None):
    if not path:
        return data

    current_data = data
    path_parts = path.split('.')

    for part in path_parts:
        if isinstance(current_data, dict):
            if part in current_data:
                current_data = current_data[part]
            else:
                return default
        elif isinstance(current_data, list):
            try:
                index = int(part)
                if 0 <= index < len(current_data):
                    current_data = current_data[index]
                else:
                    return default
            except ValueError:
                # If the part is not an integer for a list access, it's invalid
                return default
        else:
            # If we are trying to access a key/index on a non-container type
            return default

    return current_data

def flatten_dict(data, sep='.'):
    """
    Flattens nested dictionaries into a single dictionary with joined keys.
    Non-dict values are leaves. Preserves insertion traversal order.
    """
    result = {}

    def _flatten(d, parent_key=''):
        if isinstance(d, dict):
            for k, v in d.items():
                new_key = parent_key + sep + k if parent_key else k
                if isinstance(v, dict):
                    _flatten(v, new_key)
                else:
                    result[new_key] = v
        else:
            # This case should ideally not be hit if the initial call is on a dict,
            # but handles cases where a non-dict is passed directly.
            # For the top level, we assume 'data' is a dict.
            pass

    _flatten(data)
    return result

