def stable_partition(items, predicate):
    matching = []
    non_matching = []
    for item in items:
        if predicate(item):
            matching.append(item)
        else:
            non_matching.append(item)
    return (matching, non_matching)

def pairwise_deltas(values):
    if len(values) < 2:
        return []

    deltas = []
    for i in range(1, len(values)):
        delta = values[i] - values[i-1]
        deltas.append(delta)
    return deltas
